import { writeFile } from "node:fs/promises";

async function integrationWritingCodeStep(input) {
  await writeFile(
    new URL("../../generated.txt", import.meta.url),
    "generated by the integration code step\n",
  );
  return { summary: "wrote generated.txt", input };
}

export const writingStep = {
  key: "integration-step",
  name: "Integration Step",
  version: 1,
  kind: "code",
  entrypoint: { fn: integrationWritingCodeStep },
};
